<script setup lang="ts">import {computed,ref,watch} from 'vue';export type CalendarEvent={id:string;title:string;date:string;time?:string};const p=defineProps<{events?:CalendarEvent[];modelValue?:string}>();const emit=defineEmits<{'update:modelValue':[date:string];selectEvent:[id:string]}>();const current=ref(p.modelValue||new Date().toISOString().slice(0,10));watch(()=>p.modelValue,v=>{if(v)current.value=v});const year=computed(()=>Number(current.value.slice(0,4)));const month=computed(()=>Number(current.value.slice(5,7))-1);const label=computed(()=>new Intl.DateTimeFormat(undefined,{month:'long',year:'numeric'}).format(new Date(year.value,month.value,1)));const cells=computed(()=>(Array.from({length:new Date(year.value,month.value,1).getDay()},()=>null) as (number|null)[]).concat(Array.from({length:new Date(year.value,month.value+1,0).getDate()},(_,i)=>i+1)));function date(n:number){return `${year.value}-${String(month.value+1).padStart(2,'0')}-${String(n).padStart(2,'0')}`}function move(delta:number){const d=new Date(year.value,month.value+delta,1);current.value=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01`;emit('update:modelValue',current.value)}</script><template><section class="vx-calendar"><header><button type="button" aria-label="Previous month" @click="move(-1)">‹</button><h3>{{label}}</h3><button type="button" aria-label="Next month" @click="move(1)">›</button></header><div class="vx-calendar__grid"><strong v-for="day in ['Sun','Mon','Tue','Wed','Thu','Fri','Sat']" :key="day">{{day}}</strong><div v-for="(n,i) in cells" :key="i" class="vx-calendar__day"><button v-if="n" type="button" :aria-pressed="current===date(n)" @click="current=date(n);emit('update:modelValue',current)">{{n}}</button><button v-for="event in (events||[]).filter(e=>n&&e.date===date(n))" :key="event.id" type="button" class="vx-calendar__event" @click="emit('selectEvent',event.id)">{{event.title}}</button></div></div></section></template>
